static void party_first_mage_tick204(Combat*g,CampaignFollower200*m,float dt,unsigned slot){if(g->peaceful||!campaignConfig200.skills[m->id])return;if(!party_target_ok200(g,m->target)||g->mobs[m->target].life!=m->targetLife||g->time>=m->thinkAt){m->target=party_choose_target200(g,m);m->targetLife=m->target>=0?g->mobs[m->target].life:0;m->thinkAt=g->time+.15f;}if(m->target<0)return;CombatMob*enemy=g->mobs+m->target;unsigned ranks[3]={party_skill_rank193(m,3),party_skill_rank193(m,9),party_skill_rank193(m,21)},rank=0;int rates[3]={class_element_rate48(enemy,3),class_element_rate48(enemy,1),class_element_rate48(enemy,4)};unsigned skill=party_choose_bolt_values204(ranks,rates,m->sp,&rank);if(!skill)return;float reach=72;m->ownsMove=1;combat_face(&m->faceX,&m->faceY,enemy->x-m->x,enemy->y-m->y);float distance=combat_dist(m->x,m->y,enemy->x,enemy->y);if(distance<32&&distance>1){float step=party_walk_speed200(m,g->time)*fminf(dt,.05f);m->moving=combat_move(g,&m->x,&m->y,m->x+(m->x-enemy->x)/distance*step,m->y+(m->y-enemy->y)/distance*step);if(m->moving){m->elapsed+=dt;return;}}if(distance>reach){party_walk_to200(g,m,enemy->x,enemy->y,reach,dt,slot,m->target);return;}m->moving=0;if(g->time<m->nextAttack||!party_line200(g,m->x,m->y,enemy->x,enemy->y))return;const CastTiming*timing=cast_timing(skill);float dex=fminf(150,(float)party_stat200(m,4,g->time)),cast=timing?timing->cast[rank-1]*(150-dex)/150000.f:0,delay=timing?timing->delay[rank-1]/1000.f:.5f;if(cast<0)cast=0;m->pendingSkill=m->lastSkill=skill;m->pendingRank=m->remainingHits204=rank;m->pendingTarget=m->target;m->pendingLife=enemy->life;m->attackAt=g->time;m->castUntil=m->impactAt=g->time+cast;m->attackUntil=m->impactAt+(rank-1)*.2f+.3f;m->nextAttack=m->attackUntil+delay;m->skillAt=g->time+(campaignConfig200.priority[m->id]==PARTY_OFFENSE200?1.f:3.f);if(cast>0)combat_sound_at(g,58,0);}
